part of 'app.dart';
extension CommunityUI on _WorkspaceState {
 Widget announcementsView()=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[text('In the neighbourhood.',size:28,weight:FontWeight.w700),const SizedBox(height:8),text('A little more connected to the place you call home.',color:muted),const SizedBox(height:24),if(widget.admin&&me?['role']=='chairman')... [button('Post announcement',()=>newAnnouncement(),icon:Icons.campaign_outlined),const SizedBox(height:20)],...(data['announcements'] as List? ?? []).map((a)=>Padding(padding:const EdgeInsets.only(bottom:16),child:card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.campaign_outlined,color:blue,size:22),const SizedBox(width:10),text('FROM YOUR OSI',size:10,color:blue,weight:FontWeight.w700),const Spacer(),text(a['at'].toString().substring(0,10),size:11,color:muted)]),const SizedBox(height:18),text(a['title'],size:21,weight:FontWeight.w700),const SizedBox(height:12),text(a['body'],color:muted)]))))]);
 Future<void> newAnnouncement()async{final title=TextEditingController(text:'Water shut-off on Friday'),body=TextEditingController(text:'Water supply maintenance is scheduled from 10:00 to 14:00. Please prepare in advance.');String message='';bool saving=false;await showDialog<void>(context:context,builder:(dialog)=>StatefulBuilder(builder:(c,update)=>AlertDialog(title:const Text('Tell the community'),content:SizedBox(width:460,child:Column(mainAxisSize:MainAxisSize.min,children:[field(title,'Announcement title'),field(body,'Message',lines:5),text('Every resident in this building will be notified.',color:muted),if(message.isNotEmpty)text(message,color:Colors.red)])),actions:[TextButton(onPressed:()=>Navigator.pop(dialog),child:const Text('Cancel')),FilledButton(onPressed:saving?null:()async{update(()=>saving=true);try{await api.request('/announcements',method:'POST',body:{'title':title.text,'body':body.text});if(dialog.mounted)Navigator.pop(dialog);await refresh();}catch(e){if(c.mounted)update(()=>message=e.toString().replaceFirst('Exception: ',''));}finally{if(c.mounted)update(()=>saving=false);}},child:Text(saving?'Publishing…':'Publish announcement'))])));}
}
